{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2163-11-25 21:51:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I’ll be taking care of you during your stay. Can you tell me what’s been going on?"
    },
    {
      "turn_number": 2,
      "time": "2163-11-25 21:52:00",
      "speaker": "Patient",
      "text": "Hi, Doctor. I’ve been vomiting for six days now. I can’t keep anything down—not even water. I’ve barely eaten since yesterday."
    },
    {
      "turn_number": 3,
      "time": "2163-11-25 21:53:00",
      "speaker": "Doctor",
      "text": "I see. Is the vomit bloody or does it look like food?"
    },
    {
      "turn_number": 4,
      "time": "2163-11-25 21:53:30",
      "speaker": "Patient",
      "text": "No blood. It looks like the soup I tried to eat or sometimes greenish. I also feel feverish—my brother had a sore throat, but no one else is sick."
    },
    {
      "turn_number": 5,
      "time": "2163-11-25 21:54:15",
      "speaker": "Doctor",
      "text": "Okay. Any pain in your belly or when you pee?"
    },
    {
      "turn_number": 6,
      "time": "2163-11-25 21:54:45",
      "speaker": "Patient",
      "text": "I pee a lot and feel urgency, but no burning. My belly doesn’t hurt much, but I’ve had this constant body pain—worse than usual. It’s my fibromyalgia flaring up."
    },
    {
      "turn_number": 7,
      "time": "2163-11-25 21:55:30",
      "speaker": "Doctor",
      "text": "Got it. You also mentioned headaches and weight loss?"
    },
    {
      "turn_number": 8,
      "time": "2163-11-25 21:56:00",
      "speaker": "Patient",
      "text": "Yes, headache feels like my blood pressure is high. And I’ve lost about 25 pounds—mostly from not eating and my cellulitis episodes."
    },
    {
      "turn_number": 9,
      "time": "2163-11-25 21:56:45",
      "speaker": "Doctor",
      "text": "We’ll check your vitals and get some fluids into you. You look a bit dry. Since your IV access is tricky, we placed a line in your neck to help."
    },
    {
      "turn_number": 10,
      "time": "2163-11-25 21:57:30",
      "speaker": "Patient",
      "text": "That neck line feels strange, but I’ll take it if it helps. I just want to stop throwing up."
    },
    {
      "turn_number": 11,
      "time": "2163-11-25 21:58:15",
      "speaker": "Doctor",
      "text": "We gave you Zofran for nausea and morphine for pain. You haven’t vomited since arriving, which is good."
    },
    {
      "turn_number": 12,
      "time": "2163-11-25 21:59:00",
      "speaker": "Patient",
      "text": "I feel a little better, but still nauseous. Can I try sipping water?"
    },
    {
      "turn_number": 13,
      "time": "2163-11-25 21:59:30",
      "speaker": "Doctor",
      "text": "Let’s wait a few hours. We want to make sure your stomach settles. We also ordered blood and urine tests to check for infection and dehydration."
    },
    {
      "turn_number": 14,
      "time": "2163-11-26 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. Your blood work shows you’re dehydrated but no signs of kidney issues. Your phenytoin level is very low—this could increase seizure risk."
    },
    {
      "turn_number": 15,
      "time": "2163-11-26 08:16:30",
      "speaker": "Patient",
      "text": "Oh no. I haven’t taken my meds in three days because I vomited them. I haven’t had a seizure in years, but I’m scared."
    },
    {
      "turn_number": 16,
      "time": "2163-11-26 08:17:45",
      "speaker": "Doctor",
      "text": "We’re giving IV phenytoin to bring your levels up. We’ll recheck tomorrow. You’re also on Coumadin, and your INR is low—so we restarted that too."
    },
    {
      "turn_number": 17,
      "time": "2163-11-26 08:19:00",
      "speaker": "Patient",
      "text": "Thank you. What about the nausea? Is it a stomach bug?"
    },
    {
      "turn_number": 18,
      "time": "2163-11-26 08:20:15",
      "speaker": "Doctor",
      "text": "We did an abdominal X-ray—no blockage. Most likely viral gastroenteritis or gastroparesis. We’re giving IV fluids, Zofran, and Reglan to help your stomach empty."
    },
    {
      "turn_number": 19,
      "time": "2163-11-26 08:21:30",
      "speaker": "Patient",
      "text": "Reglan? I’ve never taken that before."
    },
    {
      "turn_number": 20,
      "time": "2163-11-26 08:22:00",
      "speaker": "Doctor",
      "text": "It helps with stomach motility. You’ll take it by mouth once you can keep pills down. We also started Protonix to protect your stomach."
    },
    {
      "turn_number": 21,
      "time": "2163-11-26 14:30:00",
      "speaker": "Patient",
      "text": "Doctor, I have new pain—left lower belly. Not sharp, but constant."
    },
    {
      "turn_number": 22,
      "time": "2163-11-26 14:31:15",
      "speaker": "Doctor",
      "text": "We noticed. You’re not running a fever, and your vitals are stable. We’d like to do a CT scan to check, but we need IV contrast."
    },
    {
      "turn_number": 23,
      "time": "2163-11-26 14:32:30",
      "speaker": "Patient",
      "text": "Can’t you use the neck line?"
    },
    {
      "turn_number": 24,
      "time": "2163-11-26 14:33:15",
      "speaker": "Doctor",
      "text": "Unfortunately, it wasn’t placed for contrast. And we understand you don’t want to try drinking contrast—it might make you vomit."
    },
    {
      "turn_number": 25,
      "time": "2163-11-26 14:34:00",
      "speaker": "Patient",
      "text": "No, I can’t risk it. Could this be fibromyalgia?"
    },
    {
      "turn_number": 26,
      "time": "2163-11-26 14:35:00",
      "speaker": "Doctor",
      "text": "Possibly. Fibromyalgia can cause widespread and abdominal discomfort. We’ll monitor. If pain worsens, we may reconsider imaging."
    },
    {
      "turn_number": 27,
      "time": "2163-11-27 09:00:00",
      "speaker": "Doctor",
      "text": "Your urine test came back with signs of infection—white blood cells and bacteria. We sent a culture to confirm."
    },
    {
      "turn_number": 28,
      "time": "2163-11-27 09:01:15",
      "speaker": "Patient",
      "text": "That explains the frequent urination. Is it serious?"
    },
    {
      "turn_number": 29,
      "time": "2163-11-27 09:02:00",
      "speaker": "Doctor",
      "text": "It’s a urinary tract infection. Not severe, but we’ll treat it. Once we get the culture result, we’ll pick the right antibiotic."
    },
    {
      "turn_number": 30,
      "time": "2163-11-27 09:03:00",
      "speaker": "Patient",
      "text": "I’ve had UTIs before. Will I need IV antibiotics?"
    },
    {
      "turn_number": 31,
      "time": "2163-11-27 09:03:45",
      "speaker": "Doctor",
      "text": "Not necessarily. If you can keep pills down, we’ll switch to oral meds. Your nausea is improving, so that’s promising."
    },
    {
      "turn_number": 32,
      "time": "2163-11-27 15:20:00",
      "speaker": "Doctor",
      "text": "Good news—your phenytoin level is now in the normal range. We’ll switch you back to your regular oral dose."
    },
    {
      "turn_number": 33,
      "time": "2163-11-27 15:21:30",
      "speaker": "Patient",
      "text": "That’s a relief. Any update on the infection?"
    },
    {
      "turn_number": 34,
      "time": "2163-11-27 15:22:15",
      "speaker": "Doctor",
      "text": "The culture grew Proteus mirabilis, a common UTI bug. It’s sensitive to several antibiotics, including ciprofloxacin."
    },
    {
      "turn_number": 35,
      "time": "2163-11-27 15:23:30",
      "speaker": "Patient",
      "text": "Will I take that when I go home?"
    },
    {
      "turn_number": 36,
      "time": "2163-11-27 15:24:15",
      "speaker": "Doctor",
      "text": "Yes, for seven days. We’ll also keep you on Reglan for a while to help with stomach emptying."
    },
    {
      "turn_number": 37,
      "time": "2163-11-28 08:45:00",
      "speaker": "Doctor",
      "text": "Your belly pain has improved, and you’ve had bowel movements. That’s a good sign—no obstruction."
    },
    {
      "turn_number": 38,
      "time": "2163-11-28 08:46:15",
      "speaker": "Patient",
      "text": "The pain is almost gone. I even sipped some broth yesterday without vomiting."
    },
    {
      "turn_number": 39,
      "time": "2163-11-28 08:47:30",
      "speaker": "Doctor",
      "text": "Great. We’re switching your pain meds from IV to oral—oxycodone and morphine as needed. Your fibromyalgia pain seems under control."
    },
    {
      "turn_number": 40,
      "time": "2163-11-28 08:48:45",
      "speaker": "Patient",
      "text": "I’m glad. I was worried about the IV morphine making me nauseous again."
    },
    {
      "turn_number": 41,
      "time": "2163-11-28 08:49:30",
      "speaker": "Doctor",
      "text": "We started you on a nicotine patch to help with smoking. You’ve been using the gum when cravings hit—good job staying on the floor."
    },
    {
      "turn_number": 42,
      "time": "2163-11-28 08:50:30",
      "speaker": "Patient",
      "text": "It’s hard, but I don’t want to risk falling or getting sick outside. I’m trying."
    },
    {
      "turn_number": 43,
      "time": "2163-11-29 09:15:00",
      "speaker": "Doctor",
      "text": "You’re doing well. We’ll plan for discharge tomorrow. You’re afebrile, drinking fluids, and your labs are stable."
    },
    {
      "turn_number": 44,
      "time": "2163-11-29 09:16:15",
      "speaker": "Patient",
      "text": "That’s great. What meds will I go home with?"
    },
    {
      "turn_number": 45,
      "time": "2163-11-29 09:17:30",
      "speaker": "Doctor",
      "text": "Same doses for blood pressure, thyroid, and seizure meds. You’ll take ciprofloxacin for the UTI and Reglan for nausea. Pain meds are reduced to lower doses as needed."
    },
    {
      "turn_number": 46,
      "time": "2163-11-29 09:19:00",
      "speaker": "Patient",
      "text": "And the Coumadin? Do I need a blood test?"
    },
    {
      "turn_number": 47,
      "time": "2163-11-29 09:20:00",
      "speaker": "Doctor",
      "text": "Yes. Get your INR and phenytoin level checked in one week. Call your PCP to send the results."
    },
    {
      "turn_number": 48,
      "time": "2163-11-29 09:21:15",
      "speaker": "Patient",
      "text": "What if I start vomiting again?"
    },
    {
      "turn_number": 49,
      "time": "2163-11-29 09:22:30",
      "speaker": "Doctor",
      "text": "Call your doctor or come back if you have fever over 101, severe pain, blood in stool, or can’t keep fluids down."
    },
    {
      "turn_number": 50,
      "time": "2163-11-30 10:00:00",
      "speaker": "Doctor",
      "text": "You’re cleared to go home. You’ve improved significantly—eating, drinking, and stable vitals."
    },
    {
      "turn_number": 51,
      "time": "2163-11-30 10:01:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I feel so much better."
    },
    {
      "turn_number": 52,
      "time": "2163-11-30 10:02:15",
      "speaker": "Doctor",
      "text": "You’re welcome. Keep taking your meds, stay hydrated, and follow up on your labs. We’ll see you soon."
    },
    {
      "turn_number": 53,
      "time": "2163-11-30 10:03:00",
      "speaker": "Patient",
      "text": "I will. Thanks for taking such good care of me."
    },
    {
      "turn_number": 54,
      "time": "2163-11-30 10:04:00",
      "speaker": "Doctor",
      "text": "Take care. Call us with any concerns."
    },
    {
      "turn_number": 55,
      "time": "2163-11-30 10:05:00",
      "speaker": "Patient",
      "text": "I will. Have a good day."
    },
    {
      "turn_number": 56,
      "time": "2163-11-30 10:06:00",
      "speaker": "Doctor",
      "text": "You too. Safe travels home."
    },
    {
      "turn_number": 57,
      "time": "2163-11-30 10:07:00",
      "speaker": "Patient",
      "text": "Thank you again."
    },
    {
      "turn_number": 58,
      "time": "2163-11-30 10:08:00",
      "speaker": "Doctor",
      "text": "Our pleasure. Get some rest."
    },
    {
      "turn_number": 59,
      "time": "2163-11-30 10:09:00",
      "speaker": "Patient",
      "text": "I plan to."
    },
    {
      "turn_number": 60,
      "time": "2163-11-30 10:10:00",
      "speaker": "Doctor",
      "text": "Take it easy. We’re here if you need us."
    },
    {
      "turn_number": 61,
      "time": "2163-11-30 10:11:00",
      "speaker": "Patient",
      "text": "I appreciate that."
    },
    {
      "turn_number": 62,
      "time": "2163-11-30 10:12:00",
      "speaker": "Doctor",
      "text": "All set. Nurse will bring your discharge papers."
    },
    {
      "turn_number": 63,
      "time": "2163-11-30 10:13:00",
      "speaker": "Patient",
      "text": "Okay, thanks."
    },
    {
      "turn_number": 64,
      "time": "2163-11-30 10:14:00",
      "speaker": "Doctor",
      "text": "Feel better soon."
    },
    {
      "turn_number": 65,
      "time": "2163-11-30 10:15:00",
      "speaker": "Patient",
      "text": "I already do."
    },
    {
      "turn_number": 66,
      "time": "2163-11-30 10:16:00",
      "speaker": "Doctor",
      "text": "That’s what we like to hear."
    },
    {
      "turn_number": 67,
      "time": "2163-11-30 10:17:00",
      "speaker": "Patient",
      "text": "Bye, Doctor."
    }
  ],
  "summary": {
    "admission_start": "2163-11-25 21:51:00",
    "admission_end": "2163-11-30 15:26:00",
    "summary_paragraph": "A 58-year-old female was admitted for nausea and vomiting lasting six days, with inability to tolerate oral intake and associated dehydration. She also reported urinary frequency and urgency, left lower quadrant pain, and worsening fibromyalgia pain. Initial concerns included bowel obstruction and low phenytoin levels due to missed doses. Abdominal imaging showed no obstruction. She was treated with IV fluids, antiemetics, and IV phenytoin, which was later transitioned to oral therapy as levels normalized. A urine culture confirmed Proteus mirabilis urinary tract infection, treated with ciprofloxacin. Her nausea improved with Reglan and bowel rest, and she gradually resumed oral intake. Pain was managed with IV then oral opioids. She remained seizure-free and was discharged home in stable condition with instructions to complete antibiotics, continue Reglan, and follow up on INR and phenytoin levels in one week.",
    "problems": [
      "Intestinal infection due to other organism, not elsewhere classified",
      "Urinary tract infection, site not specified",
      "Dehydration",
      "Proteus (mirabilis) (morganii) infection in conditions classified elsewhere and of unspecified site",
      "Unspecified essential hypertension",
      "Myalgia and myositis, unspecified",
      "Epilepsy, unspecified, without mention of intractable epilepsy",
      "Morbid obesity",
      "Other and unspecified hyperlipidemia",
      "Personal history of malignant neoplasm of other female genital organs",
      "Personal history of venous thrombosis and embolism",
      "Long-term (current) use of anticoagulants",
      "Obstructive sleep apnea (adult)(pediatric)",
      "Abdominal pain, left lower quadrant",
      "Unspecified acquired hypothyroidism",
      "Need for prophylactic vaccination and inoculation against influenza",
      "Tobacco use disorder"
    ]
  }
}
